R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
for w in sb_phfix sb_cafix; do mkdir -p $R/$w; cp $R/sb_cursor_probe/AGENTS.md $R/$w/AGENTS.md; done
echo  | base64 -d > $R/sb_phfix/PROMPT.md; echo  | base64 -d > $R/sb_cafix/PROMPT.md
for w in sb_phfix sb_cafix; do cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"; sleep 3; done
tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
